   Collée en haut quand la liste défile dans le cadre, comme l'en-tête de
   jarvis.table ; une ligne amenée au clavier ne finit ni dessous ni sous le
   fondu du bas de la coquille. */
:root:has(.ck-progress:not([hidden])){scroll-padding:26px 0 24px}
.ck-progress{
  position:sticky;top:0;z-index:1;display:flex;align-items:center;gap:10px;
  margin:0 -13px;padding:3px 13px 7px;background:rgba(5,11,16,.97);
}
.ck-track{position:relative;flex:1 1 auto;height:3px;border-radius:2px;overflow:hidden;background:var(--jv-edge)}
.ck-fill{
  position:absolute;inset:0;transform-origin:left center;transform:scaleX(var(--ck-ratio,0));
  background:var(--jv-accent);transition:transform .24s cubic-bezier(.22,.8,.24,1);
}
.ck-count{flex:none;font-size:calc(10px * var(--jv-scale));letter-spacing:.04em;color:var(--jv-muted);white-space:nowrap}
.ck[data-complete] .ck-count{color:color-mix(in srgb,var(--jv-accent) 78%,var(--jv-text))}

