.ck-main{flex:1 1 auto;min-width:0}
.ck-label{overflow-wrap:anywhere}
.ck-item[aria-checked="true"] .ck-label{
  color:var(--jv-muted);text-decoration:line-through 1px;
  text-decoration-color:color-mix(in srgb,var(--jv-muted) 55%,transparent);
}
.ck-note{display:block;margin-top:1px;font-size:calc(10.5px * var(--jv-scale));line-height:1.45;
  color:var(--jv-muted);white-space:pre-wrap;overflow-wrap:anywhere}

.ck-empty{padding-top:2px;font-size:calc(11.5px * var(--jv-scale))}

/* Coche non enregistrée : dite sous la liste, en ambre, puis effacée. */
.ck-notice{margin-top:8px;font-size:calc(10.5px * var(--jv-scale));color:color-mix(in srgb,#f0cf78 78%,var(--jv-text))}
.ck-notice:empty{display:none}
